async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  let normalEOF = false;

  try {
    const decoder = new TextDecoder("utf-8", {
      fatal: true,
      ignoreBOM: true
    });

    let pending = "";
    let line = 1;
    let accepted = 0;
    let rejected = 0;

    const isWhitespaceOnly = (text) => {
      for (let i = 0; i < text.length; i++) {
        const code = text.charCodeAt(i);
        if (code !== 0x20 && code !== 0x09 && code !== 0x0d) {
          return false;
        }
      }
      return true;
    };

    const processLine = async (text, lineNumber) => {
      if (isWhitespaceOnly(text)) {
        return false;
      }

      let value;
      try {
        value = JSON.parse(text);
      } catch {
        rejected++;
        return false;
      }

      accepted++;
      return (await visitor({ line: lineNumber, value })) === false;
    };

    const processText = async (text) => {
      let start = 0;

      while (true) {
        const end = text.indexOf("\n", start);

        if (end === -1) {
          pending += text.slice(start);
          return false;
        }

        pending += text.slice(start, end);

        let lineText = pending;
        if (lineText.charCodeAt(lineText.length - 1) === 0x0d) {
          lineText = lineText.slice(0, -1);
        }

        pending = "";

        const currentLine = line++;
        if (await processLine(lineText, currentLine)) {
          return true;
        }

        start = end + 1;
      }
    };

    while (true) {
      const result = await reader.read();

      if (result.done) {
        if (await processText(decoder.decode())) {
          return { accepted, rejected, stopped: true };
        }

        if (pending.length !== 0) {
          const finalLine = pending;
          pending = "";

          if (await processLine(finalLine, line)) {
            return { accepted, rejected, stopped: true };
          }
        }

        normalEOF = true;
        return { accepted, rejected, stopped: false };
      }

      if (
        await processText(decoder.decode(result.value, { stream: true }))
      ) {
        return { accepted, rejected, stopped: true };
      }
    }
  } finally {
    try {
      if (!normalEOF) {
        await reader.cancel();
      }
    } finally {
      reader.releaseLock();
    }
  }
}
